CREATE OR REPLACE FUNCTION public.require_matched_payment_image() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.reference !~ '^([0-9]{12}|screenshot:[0-9a-f]{64})$' OR NOT EXISTS(SELECT 1 FROM public.messages m WHERE m.id=NEW.message_id AND m.sender_id=NEW.payer_id AND public.has_role(m.receiver_id,'admin') AND m.image_path LIKE NEW.payer_id::text||'/%') THEN RAISE EXCEPTION 'IMAGE_AND_REFERENCE_REQUIRED'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.notify_referral_join() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF public.can_notify(NEW.referrer_id) THEN INSERT INTO public.notifications(user_id,message) VALUES(NEW.referrer_id,'మీ పరిచయ కోడ్‌తో కొత్త వ్యక్తి చేరారు. కొత్త చందా ₹100కు మూడు నెలలు; నిర్వాహకుల ఆమోదం అవసరం.'); END IF; RETURN NEW; END $$;